```yaml
name: PR Title Check
on:
  pull_request:
    types: [opened, edited, synchronize, reopened]

jobs:
  check-pr-title:
    runs-on: ubuntu-latest
    steps:
      - name: Check PR Title Format
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const prTitle = context.payload.pull_request.title;
            const prNumber = context.payload.pull_request.number;

            // Regular expression to match the required format: (TYPE) description [TASK-ID]
            const prTitleRegex = /^\([A-Za-z]+\)\s.+?\s\[[A-Z0-9]+-[0-9]+\]$/;

            if (!prTitleRegex.test(prTitle)) {
              const errorMessage = `PR title "${prTitle}" does not match the required format: "(TYPE) description [TASK-ID]"`;

              // Add a comment to the PR
              await github.rest.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: prNumber,
                body: `❌ PR title validation failed:\n\n${errorMessage}\n\nPlease update your PR title to follow this format: \`<TYPE> <description> [<TASK-ID>]\`\n\nExamples:\n- \`(feat) add new feature [DA-123]\`\n- \`(fix) resolve bug [DA-456]\`\n- \`(chore) update documentation [DA-789]\``
              });

              // Fail the check
              throw new Error(errorMessage);
            }
